<section class="editor-hero"><div><span class="eyebrow">Identidade feita com carinho</span><h2><?=$pet?'Conte ao mundo quem é '.e($pet['name']):'Quem está chegando à família?'?></h2><p>Só o nome é obrigatório. Complete os outros dados no seu tempo.</p><?php if($pet):?><code>ID único: <?=e($pet['public_id'])?></code><?php endif;?></div><div class="photo-uploader"><div class="photo-preview" data-photo-preview><?php if($pet&&$pet['main_photo_path']):?><img src="<?=asset($pet['main_photo_path'])?>" alt="Foto de <?=e($pet['name'])?>"><?php else:?><span>📷</span><?php endif;?></div><div class="photo-source-actions"><label class="btn btn-soft file-button">Escolher foto<input type="file" name="main_photo" accept="image/jpeg,image/png,image/webp,image/gif" data-photo-input></label><label class="btn btn-primary file-button">Abrir câmera<input type="file" name="main_photo_camera" accept="image/*" capture="environment" data-photo-input></label></div><small>JPG, PNG, WEBP ou GIF. O servidor validará o arquivo antes de salvar.</small><?php if($pet&&$pet['main_photo_path']):?><label class="inline-check"><input type="checkbox" name="remove_main_photo" value="1"> Remover foto atual</label><?php endif;?></div></section>
<nav class="editor-tabs" data-tabs><button type="button" class="active" data-tab="identity">Identidade</button><button type="button" data-tab="personality">Jeitinho único</button><button type="button" data-tab="health">Saúde</button><button type="button" data-tab="contact">Emergência</button><button type="button" data-tab="media">Áudio</button></nav>
<section class="editor-panel active" data-panel="identity"><div class="form-grid"><label>Nome *<input name="name" required value="<?=e($pet['name']??'')?>"></label><label>Apelido<input name="nickname" value="<?=e($pet['nickname']??'')?>"></label><label>Tipo de mascota<select name="species_id" data-species><option value="">Escolher / Outro</option><?php foreach($species as $item):?><option value="<?=e($item['id'])?>" <?=selected($pet['species_id']??'',$item['id'])?>><?=e($item['name_pt'])?></option><?php endforeach;?></select></label><label>Se não estiver na lista<input name="custom_species" value="<?=e($pet['custom_species']??'')?>" placeholder="Ex.: Furão"></label><label>Raça<select name="breed_id" data-breed><option value="">Sem raça / Outra</option><?php foreach($breeds as $item):?><option value="<?=e($item['id'])?>" data-species-id="<?=e($item['species_id'])?>" <?=selected($pet['breed_id']??'',$item['id'])?>><?=e($item['name'])?></option><?php endforeach;?></select></label><label>Raça personalizada<input name="custom_breed" value="<?=e($pet['custom_breed']??'')?>" placeholder="Escreva livremente"></label><label>Sexo<select name="sex"><option value="UNKNOWN">Não informado</option><option value="FEMALE" <?=selected($pet['sex']??'','FEMALE')?>>Fêmea</option><option value="MALE" <?=selected($pet['sex']??'','MALE')?>>Macho</option></select></label><label>Data de nascimento<input type="date" name="birth_date" value="<?=e($pet['birth_date']??'')?>"></label><label>Idade aproximada<input name="approximate_age" value="<?=e($pet['approximate_age']??'')?>" placeholder="Ex.: cerca de 5 anos"></label><label>Peso (kg)<input type="number" step="0.01" name="weight_kg" value="<?=e($pet['weight_kg']??'')?>"></label><label>Cor<input name="color" value="<?=e($pet['color']??'')?>"></label><label>Porte<select name="size"><option value="UNKNOWN">Não informado</option><option value="TINY" <?=selected($pet['size']??'','TINY')?>>Mini</option><option value="SMALL" <?=selected($pet['size']??'','SMALL')?>>Pequeno</option><option value="MEDIUM" <?=selected($pet['size']??'','MEDIUM')?>>Médio</option><option value="LARGE" <?=selected($pet['size']??'','LARGE')?>>Grande</option><option value="GIANT" <?=selected($pet['size']??'','GIANT')?>>Gigante</option></select></label><label>Microchip<input name="microchip" value="<?=e($pet['microchip']??'')?>"></label><label class="check"><input type="checkbox" name="neutered" value="1" <?=checked($pet['neutered']??false)?>> Castrado(a)</label><label>Cidade<input name="city" value="<?=e($pet['city']??'')?>"></label><label>Estado<input name="state" value="<?=e($pet['state']??'SC')?>"></label></div></section>
