<section class="editor-panel" data-panel="health"><div class="info-banner">🩺 Estes campos rápidos adicionam novos registros. O histórico completo aparece em integrações com veterinárias.</div><div class="form-grid"><label>Nova alergia<input name="new_allergy"></label><label>Gravidade<select name="allergy_severity"><option value="LOW">Baixa</option><option value="MEDIUM">Média</option><option value="HIGH">Alta</option><option value="CRITICAL">Crítica</option></select></label><label class="full">Observação da alergia<input name="allergy_notes"></label><label class="check full"><input type="checkbox" name="allergy_public" value="1"> Mostrar em emergência</label><label>Nova medicação<input name="new_medication"></label><label>Dosagem<input name="medication_dosage"></label><label>Frequência<input name="medication_frequency"></label><label class="check"><input type="checkbox" name="medication_public" value="1"> Mostrar em emergência</label><label>Nova vacina<input name="new_vaccine"></label><label>Aplicada em<input type="date" name="vaccine_date"></label><label>Próxima dose<input type="date" name="vaccine_next"></label><label>Veterinário<input name="veterinarian_name"></label></div><?php if($allergies||$medications||$vaccinations):?><div class="record-columns"><div><h3>Alergias</h3><?php foreach($allergies as $i):?><p><b><?=e($i['allergen'])?></b> · <?=e($i['severity'])?></p><?php endforeach;?></div><div><h3>Medicações</h3><?php foreach($medications as $i):?><p><b><?=e($i['name'])?></b> · <?=e($i['frequency'])?></p><?php endforeach;?></div><div><h3>Vacinas</h3><?php foreach($vaccinations as $i):?><p><b><?=e($i['vaccine_name'])?></b> · próxima <?=e($i['next_dose_at']?:'não informada')?></p><?php endforeach;?></div></div><?php endif;?></section>
<section class="editor-panel" data-panel="contact"><div class="form-grid"><label>Contato principal<input name="contact_name" value="<?=e($contacts[0]['name']??Auth::user()['name'])?>"></label><label>Telefone / WhatsApp<input name="contact_phone" inputmode="tel" value="<?=e($contacts[0]['phone']??Auth::user()['phone'])?>"></label><label>Relação<input name="contact_relationship" value="<?=e($contacts[0]['relationship']??'Tutor(a)')?>"></label><label>Recompensa opcional (R$)<input type="number" step="0.01" name="reward" value="<?=e(isset($pet)?((int)$pet['reward_cents']/100):0)?>"></label></div></section>
