<div class="sticky-save"><button class="btn btn-primary btn-lg">Salvar com carinho</button><?php if($pet):?><a class="btn btn-soft" target="_blank" href="<?=public_pet_url($pet)?>">Ver perfil público</a><a class="btn btn-ghost" href="<?=url('/owner/pets/'.$pet['id'].'/media')?>">Galeria completa</a><?php endif;?></div></form>
